package com.nigson.commerce.security;
import com.nigson.shared.security.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.problem.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.assertj.core.api.Assertions.*;
class JdbcSessionTrustTest {
 JdbcTemplate jdbc;TransactionTemplate tx;SessionCodec codec;JdbcSessionTrust store;MutableClock clock;UUID party;
 static class MutableClock extends Clock {Instant now=Instant.now();public Instant instant(){return now;}public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}}
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"make security-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));clock=new MutableClock();byte[] key=new byte[32];new java.security.SecureRandom().nextBytes(key);codec=new SessionCodec("v1",Map.of("v1",key));store=new JdbcSessionTrust(jdbc,tx,codec,clock,Set.of("/account","/"));party=UUID.randomUUID();jdbc.update("INSERT INTO commerce.party(id,created_by,updated_by,identity_issuer,identity_subject,email,display_name) VALUES (?,'test','test',?,?,?,'Synthetic security fixture')",party,SecurityProtocolTest.ISSUER,party.toString(),party+"@synthetic.invalid");}
 SessionRecord record(){return new SessionRecord(1,party,SecurityProtocolTest.ISSUER,party.toString(),clock.instant(),null,"synthetic-access","synthetic-refresh",clock.instant().plusSeconds(300),JdbcSessionTrust.opaque(),SessionRecord.TokenState.READY);}
 String login(){var l=store.begin("/account");store.consume(l.sessionId(),l.flow().state());return store.authenticate(l.sessionId(),record());}
 @Test void stateIsOneUseUnderRaceAndRotationCannotResurrectLogout()throws Exception{
  var pending=store.begin("/account");assertThatThrownBy(()->store.consume(pending.sessionId(),"wrong")).hasMessage("ACTOR_TRUST_REJECTED");var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var tasks=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{start.await();try{store.consume(pending.sessionId(),pending.flow().state());return true;}catch(org.springframework.security.access.AccessDeniedException e){return false;}}));start.countDown();assertThat(tasks.stream().map(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).filter(Boolean::booleanValue).count()).isEqualTo(1);}
  var r=record();String rotated=store.authenticate(pending.sessionId(),r);assertThat(rotated).isNotEqualTo(pending.sessionId());assertThatThrownBy(()->store.read(pending.sessionId(),true)).hasMessage("ACTOR_TRUST_REJECTED");assertThat(store.read(rotated,true)).isEqualTo(r);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.spring_session_attributes a JOIN commerce.spring_session s ON s.primary_id=a.session_primary_id WHERE s.session_id=?",Integer.class,rotated)).isEqualTo(1);
  assertThatThrownBy(()->store.consume(pending.sessionId(),pending.flow().state())).hasMessage("ACTOR_TRUST_REJECTED");assertThatThrownBy(()->store.authenticate(rotated,r)).hasMessage("ACTOR_TRUST_REJECTED");store.logout(rotated);assertThatThrownBy(()->store.authenticate(rotated,r)).hasMessage("ACTOR_TRUST_REJECTED");
 }
 @Test void idleAndAbsoluteExpiryPersistAcrossReplicaAndTokenRefreshDoesNotExtendAbsoluteTime(){String id=login();var other=new JdbcSessionTrust(jdbc,tx,codec,clock,Set.of("/account"));assertThat(other.read(id,false).party()).isEqualTo(party);clock.now=clock.now.plusSeconds(1799);other.read(id,true);clock.now=clock.now.plusSeconds(1800);String idleId=id;assertThatThrownBy(()->store.read(idleId,true)).hasMessage("ACTOR_TRUST_REJECTED");
  clock.now=Instant.now();id=login();String absoluteId=id;for(int i=0;i<23;i++){clock.now=clock.now.plusSeconds(1799);store.read(id,true);}var previous=store.read(id,false);var refreshed=new SessionRecord(1,party,previous.issuer(),previous.subject(),previous.loginAt(),null,"new-access","new-refresh",clock.instant().plusSeconds(300),previous.csrfToken(),SessionRecord.TokenState.READY);assertThat(store.replace(id,previous,refreshed)).isTrue();clock.now=previous.absoluteExpiry();assertThatThrownBy(()->other.read(absoluteId,true)).hasMessage("ACTOR_TRUST_REJECTED");}
 @Test void tokensAreEncryptedFrameworkCodecIsTypedAndLogoutCascades(){String id=login();var session=store.read(id,false);byte[] bytes=jdbc.queryForObject("SELECT a.attribute_bytes FROM commerce.spring_session_attributes a JOIN commerce.spring_session s ON s.primary_id=a.session_primary_id WHERE s.session_id=?",byte[].class,id);assertThat(new String(bytes,java.nio.charset.StandardCharsets.US_ASCII)).doesNotContain("synthetic-access","synthetic-refresh");assertThat(codec.conversionService().convert(bytes,Object.class)).isEqualTo(session);assertThatThrownBy(()->store.csrf(session,"wrong")).hasMessage("ACTOR_TRUST_REJECTED");store.csrf(session,session.csrfToken());store.logout(id);assertThat(store.replace(id,session,session)).isFalse();assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.spring_session WHERE session_id=?",Integer.class,id)).isZero();}
 @Test void currentRolesAndRevocationAreOwnedAuditedAndRollbackSafe(){String id=login();var session=store.read(id,false);var auth=new CommerceAuthority(jdbc,clock,5);assertThat(auth.resolve(session,null,Set.of()).roles()).containsExactly("CUSTOMER");UUID assignment=UUID.randomUUID();var metrics=new SimpleMeterRegistry();var audit=new AuditWriter(jdbc,clock,metrics);
  tx.executeWithoutResult(s->{jdbc.update("INSERT INTO commerce.staff_role_assignment(id,created_by,updated_by,party_id,role,granted_by) VALUES (?,'test','test',?,'ADMIN',?)",assignment,party,party);audit.append(party.toString(),AuditValues.ActorKind.USER,AuditValues.Action.STAFF_ROLE_GRANT,AuditValues.Resource.STAFF_ROLE,assignment,UUID.randomUUID(),AuditValues.Reason.SECURITY_POLICY,null,Map.of("role","ADMIN"),null);});assertThat(auth.resolve(session,null,Set.of()).roles()).contains("ADMIN").doesNotContain("FINANCE");
  assertThatThrownBy(()->tx.executeWithoutResult(s->{jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE id=?",assignment);store.revokeSubject(party);throw new IllegalStateException("rollback");})).hasMessage("rollback");assertThat(store.read(id,false)).isEqualTo(session);
  tx.executeWithoutResult(s->{jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE id=?",assignment);store.revokeSubject(party);audit.append(party.toString(),AuditValues.ActorKind.USER,AuditValues.Action.STAFF_ROLE_REVOKE,AuditValues.Resource.STAFF_ROLE,assignment,UUID.randomUUID(),AuditValues.Reason.SECURITY_POLICY,Map.of("role","ADMIN"),null,null);});assertThatThrownBy(()->store.read(id,false)).hasMessage("ACTOR_TRUST_REJECTED");assertThat(auth.resolve(session,null,Set.of()).roles()).containsExactly("CUSTOMER");assertThatThrownBy(()->auth.resolve(session,UUID.randomUUID(),Set.of())).hasMessage("ACTOR_TRUST_REJECTED");
  jdbc.update("UPDATE commerce.party SET status='SUSPENDED' WHERE id=?",party);assertThatThrownBy(()->auth.resolve(session,null,Set.of())).hasMessage("ACTOR_TRUST_REJECTED");
 }
 @Test void refreshClaimHasSingleWinnerAndUnknownOrLogoutNeverResurrectsSession(){String id=login();var old=store.read(id,false);var claimed=old.withState(SessionRecord.TokenState.REFRESHING);assertThat(store.replace(id,old,claimed)).isTrue();assertThat(store.replace(id,old,claimed)).isFalse();assertThatThrownBy(()->store.read(id,false)).hasMessage("ACTOR_TRUST_REJECTED");store.logout(id);assertThat(store.replace(id,claimed,old)).isFalse();}
 @Test void springSessionRepositoryUsesTheSameEncryptedTypedRecordAndPrincipalIndex(){var repo=new org.springframework.session.jdbc.JdbcIndexedSessionRepository(jdbc,tx);repo.setTableName("commerce.spring_session");repo.setConversionService(codec.conversionService());repo.setIndexResolver(s->Map.of(org.springframework.session.FindByIndexNameSessionRepository.PRINCIPAL_NAME_INDEX_NAME,party.toString()));org.springframework.session.SessionRepository<org.springframework.session.Session> repository=(org.springframework.session.SessionRepository)repo;var s=repository.createSession();s.setAttribute("nigson.identity",record());repository.save(s);assertThat(store.read(s.getId(),false).party()).isEqualTo(party);assertThat(repo.findByIndexNameAndIndexValue(org.springframework.session.FindByIndexNameSessionRepository.PRINCIPAL_NAME_INDEX_NAME,party.toString())).containsKey(s.getId());assertThat(store.revokeSubject(party)).isEqualTo(1);assertThat(repo.findById(s.getId())).isNull();}
 @Test void organizationContextRequiresCurrentMembershipAndExactServerSelectedEntitlement(){
  String id=login();var session=store.read(id,false);var auth=new CommerceAuthority(jdbc,clock,3);UUID org=UUID.randomUUID(),membership=UUID.randomUUID(),entitlement=UUID.randomUUID();jdbc.update("INSERT INTO commerce.organization(id,created_by,updated_by,name,country_code,status) VALUES (?,'test','test','Synthetic organization','NG','ACTIVE')",org);jdbc.update("INSERT INTO commerce.organization_membership(id,created_by,updated_by,organization_id,party_id,role,status) VALUES (?,'test','test',?,?,'BUYER','ACTIVE')",membership,org,party);jdbc.update("INSERT INTO commerce.account_entitlement(id,created_by,updated_by,organization_id,entitlement,status,source_application_id,approval_command_id) VALUES (?,'test','test',?,'TEST_BUYING','SUSPENDED',?,?)",entitlement,org,UUID.randomUUID(),UUID.randomUUID());
  assertThatThrownBy(()->auth.resolve(session,org,"TEST_BUYING",Set.of())).hasMessage("ACTOR_TRUST_REJECTED");jdbc.update("UPDATE commerce.account_entitlement SET status='ACTIVE' WHERE id=?",entitlement);assertThat(auth.resolve(session,org,"TEST_BUYING",Set.of()).organization()).isEqualTo(org);assertThatThrownBy(()->auth.resolve(session,org,"OTHER_ENTITLEMENT",Set.of())).hasMessage("ACTOR_TRUST_REJECTED");assertThatThrownBy(()->auth.resolve(session,org,Set.of())).hasMessage("ACTOR_TRUST_REJECTED");jdbc.update("UPDATE commerce.organization_membership SET status='SUSPENDED' WHERE id=?",membership);assertThatThrownBy(()->auth.resolve(session,org,"TEST_BUYING",Set.of())).hasMessage("ACTOR_TRUST_REJECTED");assertThatThrownBy(()->auth.requireOwner(auth.resolve(session,null,Set.of()),UUID.randomUUID())).hasMessage("NOT_FOUND");
 }

}
